#!/usr/bin/env python3
from __future__ import annotations

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def replace_once(path: str, old: str, new: str) -> None:
    p = ROOT / path
    text = p.read_text()
    count = text.count(old)
    if count != 1:
        raise SystemExit(f"{path}: expected one replacement target, found {count}")
    p.write_text(text.replace(old, new, 1))


def patch_service() -> None:
    path = ROOT / "apps/kernel/backend/authorization/Service.mo"
    text = path.read_text()

    if "scopeSubject : Types.AppScopeRef -> ?Types.SubjectRef" not in text:
        text = text.replace(
            "        subjectOwnsScope : (Types.SubjectRef, Types.AppScopeRef) -> Bool,\n"
            "        scopeElement : Types.AppScopeRef -> ?Text,\n",
            "        subjectOwnsScope : (Types.SubjectRef, Types.AppScopeRef) -> Bool,\n"
            "        scopeSubject : Types.AppScopeRef -> ?Types.SubjectRef,\n"
            "        scopeElement : Types.AppScopeRef -> ?Text,\n",
            1,
        )

    start = text.index("        public func issue(\n")
    end = text.index("        public func leaseCountForTesting()", start)
    replacement = '''        // Safe pre-authentication metadata inspection. Exact resource identity,\n        // provider/issuer scope, bearer material, and storage paths are absent.\n        public func inspect(input : Types.InspectInput) : ?Types.GrantInspection {\n            let ?stored = Map.get(grantsMem.grants, Text.compare, input.grant_id) else {\n                return null;\n            };\n            let grant = stored.grant;\n            ?{\n                namespace = grant.resource.namespace;\n                resource_type = grant.resource.resource_type;\n                consumer_element = grant.consumer_element;\n                rights = grant.rights;\n                expires_at = grant.expires_at;\n                revoked = effectivelyRevoked(grant);\n            };\n        };\n\n        // Redemption is the one public subject-bound operation that accepts an\n        // explicit consumer AppScope. Kernel verifies the authenticated subject\n        // owns that exact active scope and that the Element constraint matches.\n        public func redeem(\n            input : Types.RedeemInput,\n            caller : Principal,\n        ) : async* Types.RedeemResult {\n            if (caller == ANONYMOUS) return #err(#unauthenticated);\n            let ?token = parseToken(input.token) else return #err(#denied);\n            let ?stored = Map.get(grantsMem.grants, Text.compare, token.grant_id) else {\n                return #err(#denied);\n            };\n            if (not secretMatches(token.grant_id, token.secret, stored.secret_hash)) {\n                return #err(#denied);\n            };\n\n            let subject : Types.SubjectRef = #principal(caller);\n            let grant = stored.grant;\n            if (\n                not grantUsable(grant) or\n                not audienceAllows(grant.audience, subject) or\n                not CapabilityScope.valid(input.consumer_scope) or\n                not scopeActive(input.consumer_scope) or\n                not subjectOwnsScope(subject, input.consumer_scope) or\n                not scopeActive(grant.provider_scope) or\n                not consumerElementAllows(grant.consumer_element, input.consumer_scope) or\n                not redemptionAvailable(grant)\n            ) return #err(#denied);\n\n            let leaseRandom = await* freshRandom();\n            if (leaseRandom.size() < 32) return #err(#unavailable);\n            let leaseId = hex(leaseRandom);\n            let issuedAt = now();\n            let nominalLeaseExpiry = issuedAt + LEASE_LIFETIME_NS;\n            let effectiveLeaseExpiry = switch (grant.expires_at) {\n                case (?grantExpiry) {\n                    if (grantExpiry < nominalLeaseExpiry) grantExpiry\n                    else nominalLeaseExpiry;\n                };\n                case null nominalLeaseExpiry;\n            };\n            let lease : Types.AuthorizationLease = {\n                lease_id = leaseId;\n                grant_id = grant.grant_id;\n                subject;\n                consumer_scope = input.consumer_scope;\n                provider_scope = grant.provider_scope;\n                resource = grant.resource;\n                rights = grant.rights;\n                issued_at = issuedAt;\n                expires_at = effectiveLeaseExpiry;\n            };\n\n            let updatedGrant = copyGrantWithRedemptionCount(\n                grant,\n                grant.redemption_count + 1,\n            );\n            Map.add(\n                grantsMem.grants,\n                Text.compare,\n                grant.grant_id,\n                { grant = updatedGrant; secret_hash = stored.secret_hash },\n            );\n            Map.add(leases, Text.compare, leaseId, lease);\n            appendAudit(\n                "redeem",\n                ?grant.grant_id,\n                ?subject,\n                ?input.consumer_scope,\n                ?grant.provider_scope,\n                ?grant.resource,\n            );\n            #ok(lease);\n        };\n\n        // One compiler-delivered capability is bound to one exact AppScope.\n        // Provider management and consumer lease operations cannot substitute a\n        // sibling scope because no method accepts a scope selector.\n        public func authorizationCapability(\n            boundScope : Types.AppScopeRef,\n        ) : Types.AuthorizationCapabilityV1 {\n            {\n                issue = func(input : Types.IssueInput) : async* Types.IssueResult {\n                    await* issueFromScope(boundScope, input);\n                };\n                list = func() : [Types.AuthorizationGrant] {\n                    listFromScope(boundScope);\n                };\n                revoke = func(input : Types.RevokeInput) : Types.MutationResult {\n                    revokeFromScope(boundScope, input);\n                };\n                rotate_resource = func(\n                    input : Types.RotateResourceInput\n                ) : Types.MutationResult {\n                    rotateResourceFromScope(boundScope, input);\n                };\n                register_provider = func(dispatch : Types.ProviderDispatch) : () {\n                    registerProviderFromScope(boundScope, dispatch);\n                };\n                call = func(\n                    input : Types.AuthorizedCallInput\n                ) : async* Types.AuthorizedCallResult {\n                    await* callFromScope(boundScope, input);\n                };\n                delegate = func(input : Types.DelegateInput) : async* Types.IssueResult {\n                    await* delegateFromScope(boundScope, input);\n                };\n                release = func(input : Types.ReleaseInput) : () {\n                    releaseFromScope(boundScope, input.lease_id);\n                };\n            };\n        };\n\n'''
    text = text[:start] + replacement + text[end:]

    marker = "        func callFromScope(\n"
    helpers = '''        func issueFromScope(\n            providerScope : Types.AppScopeRef,\n            input : Types.IssueInput,\n        ) : async* Types.IssueResult {\n            if (\n                not CapabilityScope.valid(providerScope) or\n                not scopeActive(providerScope) or\n                not validResource(input.resource) or\n                not validRights(input.rights) or\n                expiredAtCreation(input.expires_at)\n            ) return #err(#not_authorized);\n            let ?subject = scopeSubject(providerScope) else {\n                return #err(#not_authorized);\n            };\n            if (not subjectOwnsScope(subject, providerScope)) {\n                return #err(#not_authorized);\n            };\n\n            await* createGrant(\n                subject,\n                providerScope,\n                providerScope,\n                input.resource,\n                input.audience,\n                input.consumer_element,\n                normalizeRights(input.rights),\n                input.expires_at,\n                null,\n                input.max_redemptions,\n            );\n        };\n\n        func listFromScope(\n            issuerScope : Types.AppScopeRef,\n        ) : [Types.AuthorizationGrant] {\n            if (\n                not CapabilityScope.valid(issuerScope) or\n                not scopeActive(issuerScope)\n            ) return [];\n            var result : [Types.AuthorizationGrant] = [];\n            for ((_, stored) in Map.entries(grantsMem.grants)) {\n                if (CapabilityScope.equal(stored.grant.issuer_scope, issuerScope)) {\n                    result := Array.concat(result, [stored.grant]);\n                };\n            };\n            result;\n        };\n\n        func revokeFromScope(\n            issuerScope : Types.AppScopeRef,\n            input : Types.RevokeInput,\n        ) : Types.MutationResult {\n            if (\n                not CapabilityScope.valid(issuerScope) or\n                not scopeActive(issuerScope)\n            ) return #err(#not_authorized);\n            let ?stored = Map.get(grantsMem.grants, Text.compare, input.grant_id) else {\n                return #err(#denied);\n            };\n            if (not CapabilityScope.equal(stored.grant.issuer_scope, issuerScope)) {\n                return #err(#not_authorized);\n            };\n            let ?subject = scopeSubject(issuerScope) else {\n                return #err(#not_authorized);\n            };\n            if (stored.grant.issuer_subject != subject) {\n                return #err(#not_authorized);\n            };\n\n            if (stored.grant.revoked_at == null) {\n                let revoked = copyGrantWithRevokedAt(stored.grant, ?now());\n                Map.add(\n                    grantsMem.grants,\n                    Text.compare,\n                    input.grant_id,\n                    { grant = revoked; secret_hash = stored.secret_hash },\n                );\n                appendAudit(\n                    "revoke",\n                    ?input.grant_id,\n                    ?subject,\n                    null,\n                    ?stored.grant.provider_scope,\n                    ?stored.grant.resource,\n                );\n            };\n            #ok;\n        };\n\n        func rotateResourceFromScope(\n            providerScope : Types.AppScopeRef,\n            input : Types.RotateResourceInput,\n        ) : Types.MutationResult {\n            if (\n                not CapabilityScope.valid(providerScope) or\n                not scopeActive(providerScope) or\n                not validResource(input.resource)\n            ) return #err(#not_authorized);\n            let ?subject = scopeSubject(providerScope) else {\n                return #err(#not_authorized);\n            };\n            if (not subjectOwnsScope(subject, providerScope)) {\n                return #err(#not_authorized);\n            };\n\n            let key = resourceKey(providerScope, input.resource);\n            let current = resourceEpoch(providerScope, input.resource);\n            if (current == 18_446_744_073_709_551_615) return #err(#unavailable);\n            Map.add(epochsMem.epochs, Text.compare, key, current + 1);\n            appendAudit(\n                "rotate_resource",\n                null,\n                ?subject,\n                null,\n                ?providerScope,\n                ?input.resource,\n            );\n            #ok;\n        };\n\n        func registerProviderFromScope(\n            providerScope : Types.AppScopeRef,\n            dispatch : Types.ProviderDispatch,\n        ) : () {\n            if (\n                CapabilityScope.valid(providerScope) and\n                scopeActive(providerScope)\n            ) {\n                Map.add(\n                    providerDispatch,\n                    Text.compare,\n                    CapabilityScope.key(providerScope),\n                    dispatch,\n                );\n            };\n        };\n\n'''
    text = text.replace(marker, helpers + marker, 1)

    old_release = '''        func releaseFromScope(consumerScope : Types.AppScopeRef, leaseId : Text) : () {\n            switch (Map.get(leases, Text.compare, leaseId)) {\n                case (?lease) {\n                    if (CapabilityScope.equal(lease.consumer_scope, consumerScope)) {\n                        Map.remove(leases, Text.compare, leaseId);\n                    };\n                };\n                case null {};\n            };\n        };\n'''
    new_release = '''        func releaseFromScope(consumerScope : Types.AppScopeRef, leaseId : Text) : () {\n            switch (Map.get(leases, Text.compare, leaseId)) {\n                case (?lease) {\n                    if (CapabilityScope.equal(lease.consumer_scope, consumerScope)) {\n                        ignore Map.remove(leases, Text.compare, leaseId);\n                        appendAudit(\n                            "release",\n                            ?lease.grant_id,\n                            ?lease.subject,\n                            ?lease.consumer_scope,\n                            ?lease.provider_scope,\n                            ?lease.resource,\n                        );\n                    };\n                };\n                case null {};\n            };\n        };\n'''
    if old_release in text:
        text = text.replace(old_release, new_release, 1)

    text = text.replace("MTN 0.2", "multitenancy-neutron 0.2")
    path.write_text(text)


def patch_public_capabilities() -> None:
    path = ROOT / "packages/neutron-motoko-capabilities/src/lib.mo"
    text = path.read_text()
    start_marker = "module {\n    // MTN 0.2 resource-authorization contracts."
    start = text.index(start_marker)
    deferred = text.index("    public type DeferredTimerPhaseV1", start)
    block = '''module {\n    // multitenancy-neutron 0.2 resource-authorization contracts. AppScope is\n    // the existing Neutron installation identity; ResourceRef is provider-defined.\n    public type AuthorizationAppScopeRefV1 = {\n        app_id : Text;\n        installation_uid : Nat64;\n    };\n    public type AuthorizationSubjectRefV1 = { #principal : Principal };\n    public type AuthorizationResourceRefV1 = {\n        namespace : Text;\n        resource_id : Text;\n        resource_type : Text;\n    };\n    public type AuthorizationAudienceV1 = {\n        #any_authenticated;\n        #principal : Principal;\n    };\n    public type AuthorizationRightV1 = { #read; #write; #reshare };\n    public type AuthorizationGrantV1 = {\n        grant_id : Text;\n        issuer_subject : AuthorizationSubjectRefV1;\n        issuer_scope : AuthorizationAppScopeRefV1;\n        provider_scope : AuthorizationAppScopeRefV1;\n        resource : AuthorizationResourceRefV1;\n        audience : AuthorizationAudienceV1;\n        consumer_element : ?Text;\n        rights : [AuthorizationRightV1];\n        created_at : Nat64;\n        expires_at : ?Nat64;\n        revoked_at : ?Nat64;\n        parent_grant_id : ?Text;\n        resource_authorization_epoch : Nat64;\n        max_redemptions : ?Nat;\n        redemption_count : Nat;\n    };\n    public type AuthorizationIssueInputV1 = {\n        resource : AuthorizationResourceRefV1;\n        audience : AuthorizationAudienceV1;\n        consumer_element : ?Text;\n        rights : [AuthorizationRightV1];\n        expires_at : ?Nat64;\n        max_redemptions : ?Nat;\n    };\n    public type AuthorizationIssueOutputV1 = {\n        grant : AuthorizationGrantV1;\n        token : Text;\n    };\n    public type AuthorizationErrorV1 = {\n        #invalid_request;\n        #unauthenticated;\n        #not_authorized;\n        #denied;\n        #unavailable;\n    };\n    public type AuthorizationIssueResultV1 = {\n        #ok : AuthorizationIssueOutputV1;\n        #err : AuthorizationErrorV1;\n    };\n    public type AuthorizationMutationResultV1 = {\n        #ok;\n        #err : AuthorizationErrorV1;\n    };\n    public type AuthorizationLeaseV1 = {\n        lease_id : Text;\n        grant_id : Text;\n        subject : AuthorizationSubjectRefV1;\n        consumer_scope : AuthorizationAppScopeRefV1;\n        provider_scope : AuthorizationAppScopeRefV1;\n        resource : AuthorizationResourceRefV1;\n        rights : [AuthorizationRightV1];\n        issued_at : Nat64;\n        expires_at : Nat64;\n    };\n    public type AuthorizationContextV1 = {\n        grant_id : Text;\n        lease_id : Text;\n        subject : AuthorizationSubjectRefV1;\n        consumer_scope : AuthorizationAppScopeRefV1;\n        provider_scope : AuthorizationAppScopeRefV1;\n        resource : AuthorizationResourceRefV1;\n        rights : [AuthorizationRightV1];\n    };\n    public type AuthorizationCallInputV1 = {\n        lease_id : Text;\n        requested_right : AuthorizationRightV1;\n        operation : Text;\n        payload : Blob;\n    };\n    public type AuthorizationCallRequestV1 = {\n        authorization : AuthorizationContextV1;\n        operation : Text;\n        payload : Blob;\n    };\n    public type AuthorizationCallResultV1 = {\n        #ok : Blob;\n        #denied;\n        #provider_unavailable;\n    };\n    public type AuthorizationDelegateInputV1 = {\n        lease_id : Text;\n        audience : AuthorizationAudienceV1;\n        consumer_element : ?Text;\n        rights : [AuthorizationRightV1];\n        expires_at : ?Nat64;\n        max_redemptions : ?Nat;\n    };\n    public type AuthorizationV1 = {\n        issue : AuthorizationIssueInputV1 -> async* AuthorizationIssueResultV1;\n        list : () -> [AuthorizationGrantV1];\n        revoke : { grant_id : Text } -> AuthorizationMutationResultV1;\n        rotate_resource : { resource : AuthorizationResourceRefV1 } -> AuthorizationMutationResultV1;\n        register_provider : (AuthorizationCallRequestV1 -> async* Blob) -> ();\n        call : AuthorizationCallInputV1 -> async* AuthorizationCallResultV1;\n        delegate : AuthorizationDelegateInputV1 -> async* AuthorizationIssueResultV1;\n        release : { lease_id : Text } -> ();\n    };\n\n'''
    path.write_text(block + text[deferred:])


def patch_main() -> None:
    path = ROOT / "apps/kernel/backend/main.mo"
    text = path.read_text()

    start = text.index("        let authorization = AuthorizationService.Service(\n")
    end = text.index("\n\n        func dedicatedResidentOriginActive(", start)
    block = '''        let authorization = AuthorizationService.Service(\n            authorizationGrantsMem,\n            authorizationEpochsMem,\n            authorizationAuditMem,\n            func(scope : CapabilityTypes.AppScope) : Bool {\n                if (not InstallMemory.scopeActive(\n                    mem.install,\n                    runningDeploymentId,\n                    scope,\n                )) return false;\n                switch (Map.get(\n                    appInstanceLifecycleMem.retired,\n                    Text.compare,\n                    scope.app_id,\n                )) {\n                    case (?true) false;\n                    case _ true;\n                };\n            },\n            func(\n                subject : AuthorizationTypes.SubjectRef,\n                scope : CapabilityTypes.AppScope,\n            ) : Bool {\n                let #principal(principal) = subject;\n                if (principal == Principal.fromText("2vxsx-fae")) return false;\n                switch (Map.get(tenantsMem.grants, Principal.compare, principal)) {\n                    case null false;\n                    case (?apps) Array.any(\n                        apps,\n                        func(appId : Text) : Bool { appId == scope.app_id },\n                    );\n                };\n            },\n            func(scope : CapabilityTypes.AppScope) : ?AuthorizationTypes.SubjectRef {\n                var found : ?Principal = null;\n                for ((principal, apps) in Map.entries(tenantsMem.grants)) {\n                    if (Array.any(\n                        apps,\n                        func(appId : Text) : Bool { appId == scope.app_id },\n                    )) {\n                        switch (found) {\n                            case null { found := ?principal };\n                            case (?existing) {\n                                if (existing != principal) return null;\n                            };\n                        };\n                    };\n                };\n                switch (found) {\n                    case (?principal) ?#principal(principal);\n                    case null null;\n                };\n            },\n            func(scope : CapabilityTypes.AppScope) : ?Text {\n                switch (Map.get(\n                    appInstancesMem.instances,\n                    Text.compare,\n                    scope.app_id,\n                )) {\n                    case (?element) ?element;\n                    case null ?scope.app_id;\n                };\n            },\n            func() : async* Blob { await IC.management.raw_rand() },\n            nowNanos,\n        );'''
    text = text[:start] + block + text[end:]

    text = text.replace(
        '''        public func authorization_capability(\n            appScope : CapabilityTypes.AppScope,\n        ) : AuthorizationTypes.AuthorizationCapabilityV1 {\n            authorization.consumerCapability(appScope);\n        };\n''',
        '''        public func authorization_capability(\n            appScope : CapabilityTypes.AppScope,\n        ) : AuthorizationTypes.AuthorizationCapabilityV1 {\n            authorization.authorizationCapability(appScope);\n        };\n''',
        1,
    )

    for method in [
        '''        public func /*update:unauthorized*/kernel_authorization_issue(\n            input : AuthorizationTypes.IssueInput,\n            /*caller*/ caller : Principal,\n        ) : async* AuthorizationTypes.IssueResult {\n            await* authorization.issue(input, caller);\n        };\n\n''',
        '''        public func /*query:unauthorized*/kernel_authorization_list(\n            input : AuthorizationTypes.ListInput,\n            /*caller*/ caller : Principal,\n        ) : [AuthorizationTypes.AuthorizationGrant] {\n            authorization.list(input, caller);\n        };\n\n''',
        '''        public func /*update:unauthorized*/kernel_authorization_release(\n            input : AuthorizationTypes.ReleaseInput,\n            /*caller*/ caller : Principal,\n        ) : AuthorizationTypes.MutationResult {\n            authorization.release(input, caller);\n        };\n\n''',
        '''        public func /*update:unauthorized*/kernel_authorization_revoke(\n            input : AuthorizationTypes.RevokeInput,\n            /*caller*/ caller : Principal,\n        ) : AuthorizationTypes.MutationResult {\n            authorization.revoke(input, caller);\n        };\n\n''',
        '''        public func /*update:unauthorized*/kernel_authorization_rotate_resource(\n            input : AuthorizationTypes.RotateResourceInput,\n            /*caller*/ caller : Principal,\n        ) : AuthorizationTypes.MutationResult {\n            authorization.rotateResource(input, caller);\n        };\n\n''',
    ]:
        if method not in text:
            raise SystemExit("apps/kernel/backend/main.mo: expected insecure public authorization method")
        text = text.replace(method, "", 1)

    path.write_text(text)


def patch_manifest() -> None:
    path = ROOT / "apps/kernel/neutron.json"
    data = json.loads(path.read_text())
    for name in [
        "kernel_authorization_issue",
        "kernel_authorization_list",
        "kernel_authorization_release",
        "kernel_authorization_revoke",
        "kernel_authorization_rotate_resource",
    ]:
        data["func"].pop(name, None)
    path.write_text(json.dumps(data, indent=2) + "\n")


def main() -> None:
    patch_service()
    patch_public_capabilities()
    patch_main()
    patch_manifest()


if __name__ == "__main__":
    main()
